-- Daily challenges for 2026-10-11: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-11

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('living-less-rushed', 'Living Less Rushed', 'For anyone who hurries through everything, even when there is no real deadline. Each day is one small way to build in a little extra time, slow one ordinary activity down, and notice that most things go fine at an easier pace.', 'Mindfulness', 365, array['Stress', 'Mindfulness']::text[], 1, '2026-10-11T17:00:00+00:00'::timestamptz),
  ('giving-back-to-your-community', 'Giving Back to Your Community', 'For anyone who would like to help out beyond their own four walls but is not sure where to start. Each day is one small, doable way to give some time, skill or care to the community around you, at whatever scale fits your life.', 'Kindness', 365, array['Values', 'Relationships']::text[], 1, '2026-10-11T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('living-less-rushed', 'giving-back-to-your-community');

